      !t
      || typeof normalizeReadDataPath !== "function"
      || typeof expressionUsesReadData !== "function"
      || typeof validateReadDataExpressionUsage !== "function"
      || typeof extractReadDataPaths !== "function"
      || typeof parseCsvMatrix !== "function"
