        ctx.fillRect(x, 0, cellSize, cellSize);
        ctx.strokeStyle = "#d9e3ee";
        ctx.strokeRect(x + 0.5, 0.5, Math.max(0, cellSize - 1), Math.max(0, cellSize - 1));
